def trim_messages(messages, keep_last=12):
    sys = [m for m in messages if m.get("role") == "system"]
    rest = [m for m in messages if m.get("role") != "system"]
    if len(rest) <= keep_last:
        return sys + rest
    # 简单滑动：只留最后 N 条（生产中要避开拆开的 tool 对）
    return sys + rest[-keep_last:]

