ALLOWED = {"draft", "wait_confirm", "execute", "done", "aborted"}

def reduce(state: dict, event: str) -> dict:
    s = state["status"]
    if s == "draft" and event == "submit":
        return {**state, "status": "wait_confirm"}
    if s == "wait_confirm" and event == "approve":
        return {**state, "status": "execute"}
    if s == "wait_confirm" and event == "reject":
        return {**state, "status": "aborted"}
    if s == "execute" and event == "success":
        return {**state, "status": "done"}
    raise ValueError(f"非法转移 {s} + {event}")

