def stream_chat(messages):
    stream = client.chat.completions.create(
        model="gpt-4.1-mini",
        messages=messages,
        stream=True,
    )
    full = ""
    for chunk in stream:
        delta = chunk.choices[0].delta.content or ""
        full += delta
        if delta:
            yield {"type": "token", "text": delta}
    yield {"type": "done", "text": full}

