import time, random

def with_retry(fn, times=3):
    delay = 0.5
    last = None
    for i in range(times):
        try:
            return fn()
        except RetryableError as e:
            last = e
            time.sleep(delay + random.random() * 0.2)
            delay *= 2
    raise last

class RetryableError(Exception):
    pass

def grade(trace: dict, expect: dict) -> dict:
    tools = [t["name"] for t in trace.get("tools", [])]
    ok_tool = expect["must_tool"] in tools if "must_tool" in expect else True
    ok_text = expect.get("contains", "") in (trace.get("final") or "")
    return {
        "pass": ok_tool and ok_text,
        "steps": trace.get("steps"),
        "ok_tool": ok_tool,
        "ok_text": ok_text,
    }

